import{_ as o,c as d,o as n,a0 as c}from"./chunks/framework.CAoHpFZS.js";const i="/images/%E6%95%B0%E6%8D%AE%E5%BA%93/mysql/%E7%B4%A2%E5%BC%95/img.png",a="/images/%E6%95%B0%E6%8D%AE%E5%BA%93/mysql/%E7%B4%A2%E5%BC%95/img_3.png",h=JSON.parse('{"title":"索引","description":"","frontmatter":{},"headers":[],"relativePath":"article/数据库/mysql/索引/index.md","filePath":"article/数据库/mysql/索引/index.md"}'),t={name:"article/数据库/mysql/索引/index.md"};function r(l,e,s,p,m,g){return n(),d("div",null,e[0]||(e[0]=[c('<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to &quot;索引&quot;">​</a></h1><p>索引（Index）是帮助<code>MySQL</code>高效获取数据的数据结构，简单来说，索引是一种数据结构。以协助快速查询、 更新数据库表中数据。</p><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><p><img src="'+i+'" alt="img.png"></p><h3 id="在innodb中的索引" tabindex="-1">在<code>InnoDB</code>中的索引 <a class="header-anchor" href="#在innodb中的索引" aria-label="Permalink to &quot;在`InnoDB`中的索引&quot;">​</a></h3><p>使用<code>B+Tree</code>作为索引结构 聚簇索引一般以 <code>主键/唯一键/隐藏row_id</code>作为索引 非聚簇索引一般是除了上述以外建立的索引，然后将这些索引关联聚簇索引，从而形成B+树</p><p><strong>聚簇索引（<code>Clustered Index</code>）</strong> 索引的叶子节点存储的是数据行，可以直接访问完整的数据 每个表只能有一个聚簇索引，通常是主键索引，适合范围查询和排序</p><p><strong>优点</strong></p><ol><li>数据访问更快，因为聚簇索引将索引和数据保存在同一个<code>B+</code>树中，因此从聚簇索引中获取数据比非聚簇索引更快</li><li>聚簇索引对于主键的排序查找和范围查找速度非常快</li><li>按照聚簇索引排列顺序，查询显示一定范围数据的时候，由于数据都是紧密相连，数据库不用从多个数据块中提取数据，所以 节省了大量的io操作 。</li></ol><p><strong>缺点</strong></p><ol><li>插入速度严重依赖于插入顺序，按照主键的顺序插入是最快的方式，否则将会出现页分裂，严重影响性能。因此，对于<code>InnoDB</code>表，我们一般都会定义一个自增的<code>ID</code>列为主键</li><li>更新主键的代价很高，因为将会导致被更新的行移动。因此，对于<code>InnoDB</code>表，我们一般定义主键为不可更新。</li><li>二级索引访问需要两次索引查找，第一次找到主键值，第二次根据主键值找到行数据</li></ol><p><strong>限制</strong></p><ol><li>对于<code>MySQL</code>数据库中只有InnoDB支持聚簇索引，而<code>MyISAM</code>不支持聚簇索引。</li><li>由于数据物理存储方式只能有一种，而每个<code>MySQL</code>的表只能有一个聚簇索引，一般情况下就是该表的主键。</li><li>为了充分利用聚簇索引的聚簇的特性，索引<code>InnoDB</code>表的主键列尽量选用有序的id，而不建议使用无需的id，比如uuid，md5，hash，字符串作为主键将无法保证数据的顺序增常。</li></ol><p><strong>非聚簇索引（<code>Non-clustered Index</code>）</strong> 也称辅助索引在聚簇索引之上创建的索引称之为辅助索引，辅助索引访问数据总是需要二次查找。辅助索引叶子节点存储的不再是行的物理位置， 而是聚簇索引。通过辅助索引首先找到的是聚簇索引，再通过聚簇索引找到数据行的数据页，再通过数据页中的Page Directory找到数据行。<code>Innodb</code>辅助索引的叶子节点并不包含行数据， 叶子节点除了包含键值外，还包含了相应行数据的聚簇索引键。辅助索引的存在不影响数据在聚簇索引中的组织，所以一张表可以有多个辅助索引。在<code>Innodb</code>中有时也称辅助索引为二级索引。</p><p>在<code>InnoDB</code>中，表数据文件是按<code>B+Tree</code>组织的一个索引结构，这棵树的叶节点<code>data</code>域保存了完整的数据记录。 <img src="'+a+'" alt="img_3.png"></p>',15)]))}const _=o(t,[["render",r]]);export{h as __pageData,_ as default};
